/* Aliflam local region dropdown engine. No fetch/API/Apps Script calls for region selection. */
(function(){
  'use strict';
  const data=window.ALIFLAM_WILAYAH_DATA||[];
  const $=id=>document.getElementById(id);
  const upper=s=>String(s||'').trim().toLocaleUpperCase('id-ID');
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fill=(el,items,placeholder)=>{el.innerHTML='<option value="">'+esc(placeholder)+'</option>'+(items||[]).map(x=>'<option value="'+esc(x.n)+'">'+esc(x.n)+'</option>').join('');el.disabled=!(items&&items.length)};
  function init(saved){
    if(!data.length)throw new Error('Data wilayah statis kosong.');
    const province=$('checkoutProvince'),city=$('checkoutCity'),district=$('checkoutDistrict'),village=$('checkoutVillage'),postal=$('checkoutPostal');
    $('provinceOptions').innerHTML=data.map(p=>'<option value="'+esc(p.n)+'"></option>').join('');
    let selectedProvince=null,selectedCity=null,selectedDistrict=null;
    function clearCity(){selectedProvince=null;selectedCity=null;selectedDistrict=null;fill(city,[],'Pilih provinsi terlebih dahulu');fill(district,[],'Pilih kabupaten/kota terlebih dahulu');fill(village,[],'Pilih kecamatan terlebih dahulu');postal.value=''}
    function provinceChanged(){const p=data.find(x=>x.n===upper(province.value));province.value=p?p.n:province.value;clearCity();if(!p)return;selectedProvince=p;fill(city,p.c,'Pilih kabupaten/kota');}
    function cityChanged(){selectedCity=selectedProvince?.c.find(x=>x.n===city.value)||null;selectedDistrict=null;fill(district,selectedCity?.d||[],'Pilih kecamatan');fill(village,[],'Pilih kecamatan terlebih dahulu');postal.value=''}
    function districtChanged(){selectedDistrict=selectedCity?.d.find(x=>x.n===district.value)||null;fill(village,selectedDistrict?.v.map((x,i)=>({n:x[0],i}))||[],'Pilih desa/kelurahan');postal.value=''}
    function villageChanged(){const found=selectedDistrict?.v.find(x=>x[0]===village.value);postal.value=found?found[1]:''}
    province.addEventListener('input',()=>{province.value=upper(province.value);clearCity()});
    province.addEventListener('change',provinceChanged);
    city.addEventListener('change',cityChanged);
    district.addEventListener('change',districtChanged);
    village.addEventListener('change',villageChanged);
    // Restore the saved address entirely from the local dataset.
    if(saved&&saved.province){
      province.value=upper(saved.province);provinceChanged();
      if(selectedProvince){city.value=upper(saved.city);cityChanged();}
      if(selectedCity){district.value=upper(saved.district);districtChanged();}
      if(selectedDistrict){village.value=upper(saved.village);villageChanged();}
      if(saved.postalCode&&postal.value!==saved.postalCode)postal.value=postal.value||saved.postalCode;
    }
  }
  window.AliflamWilayahInit=init;
})();
